export const motivation={"ar":[{"text":"خطوة صغيرة كل يوم تصنع طريقًا طويلًا.","source":"PomoMental","sourceUrl":null,"kind":"original"},{"text":"ليس مطلوبًا أن تفهم كل شيء الآن؛ ابدأ بالسؤال التالي.","source":"PomoMental","sourceUrl":null,"kind":"original"},{"text":"ساعة هادئة من العمل أفضل من يوم كامل من تأنيب النفس.","source":"PomoMental","sourceUrl":null,"kind":"original"},{"text":"قارن تقدمك بأمس، لا ببداية شخص آخر.","source":"PomoMental","sourceUrl":null,"kind":"original"},{"text":"التعثر معلومة عن الطريقة، وليس حكمًا على قدراتك.","source":"PomoMental","sourceUrl":null,"kind":"original"},{"text":"هدفك اليوم أن تتعلم شيئًا واضحًا، لا أن تنهي العالم.","source":"PomoMental","sourceUrl":null,"kind":"original"},{"text":"الراحة جزء من الاستمرار. خذها ثم عد بخطوة صغيرة.","source":"PomoMental","sourceUrl":null,"kind":"original"},{"text":"إذا صعب الدرس، قسمه إلى سؤال واحد.","source":"PomoMental","sourceUrl":null,"kind":"original"},{"text":"ما تكرره بهدوء يصبح أسهل مع الوقت.","source":"PomoMental","sourceUrl":null,"kind":"original"},{"text":"المحاولة الجيدة تشمل تغيير الطريقة عندما لا تنفع.","source":"PomoMental","sourceUrl":null,"kind":"original"}],"en":[{"text":"Progress grows through sustained effort over time. Make this session one small step toward a goal that matters to you.","source":"Inspired by Angela Duckworth · TED","sourceUrl":"https://www.ted.com/talks/angela_lee_duckworth_grit_the_power_of_passion_and_perseverance","kind":"paraphrase"},{"text":"Not understanding something yet is a place to begin. Try a different strategy, ask a question, and give yourself time to learn.","source":"Inspired by Carol Dweck · TED","sourceUrl":"https://www.ted.com/talks/carol_dweck_the_power_of_believing_that_you_can_improve","kind":"paraphrase"},{"text":"Tasks without deadlines are easy to postpone. Give the next small task a clear start: this focus session.","source":"Inspired by Tim Urban · TED","sourceUrl":"https://www.ted.com/talks/tim_urban_inside_the_mind_of_a_master_procrastinator","kind":"paraphrase"},{"text":"You do not need a perfect day to have a useful session.","source":"PomoMental","sourceUrl":null,"kind":"original"},{"text":"Choose one question. Give it your attention. Then choose the next.","source":"PomoMental","sourceUrl":null,"kind":"original"},{"text":"A break is part of your work, not a reward you must earn.","source":"PomoMental","sourceUrl":null,"kind":"original"},{"text":"Your progress is measured in what you practise, not how busy you look.","source":"PomoMental","sourceUrl":null,"kind":"original"},{"text":"A difficult page can become a familiar page, one pass at a time.","source":"PomoMental","sourceUrl":null,"kind":"original"},{"text":"Keep the goal small enough to begin and clear enough to finish.","source":"PomoMental","sourceUrl":null,"kind":"original"}]};
export const breakTips={"ar":["ممنوع مسك الجوال. قم من مكانك وتحرك قليلًا.","ممنوع مسك الجوال. اشرب ماءً بهدوء وانظر بعيدًا عن الشاشة.","ممنوع مسك الجوال. أرخِ كتفيك وخذ أنفاسًا هادئة.","ممنوع مسك الجوال. جهّز سؤالًا واحدًا تبدأ به الجلسة القادمة.","ممنوع مسك الجوال. افتح النافذة أو غيّر جلستك قليلًا."],"en":["No phone during the break. Stand up and move a little.","No phone during the break. Have some water and look away from the screen.","No phone during the break. Relax your shoulders and take a few calm breaths.","No phone during the break. Pick one question for your next session.","No phone during the break. Stretch gently and reset your workspace."]};
